// Static game data generated by scripts/build-data.py from the 4.20 TSVs.
import jobsJson from '../data/jobs.json';
import workplacesJson from '../data/workplaces.json';
import residencesJson from '../data/residences.json';
import decorJson from '../data/decor.json';
import pathsJson from '../data/paths.json';
import treesJson from '../data/trees.json';
import landJson from '../data/land.json';

export interface Cost { coins: number; utopium: number; chroma: number }

export interface JobData {
  id: number; name: string; displayName: string; parent1: string; parent2: string;
  group: string; type: string; maleName: string; femaleName: string; quote: string;
  workplaces: string[]; requires: string;
}
export interface WorkplaceData {
  name: string; displayName: string; workingTimeMin: number; multiplier: number; jobs: string[];
  maxOccupancy: number; baseConstructionSec: number; special: string; buildType: string;
  category: string; buildable: boolean; size: number; cells: number[][];
}
export interface ResidenceData {
  name: string; displayName: string; population: number; baseConstructionSec: number; cost: Cost;
  costType: string; landCost: number; size: number; cells: number[][]; kind: string;
}
export interface DecorData {
  id: number; name: string; displayName: string; spirit: number; cost: Cost | null; landCost: number;
  category: string; size: number; cells: number[][];
}
export interface PathData { name: string; displayName: string; cost: Cost | null; landCost: number; pathType: string }
export interface TreeData { name: string; displayName: string; cost: Cost | null; landCost: number }
export interface LandRow { level: number; cost: number; land: number; utopium: number }

export const JOBS = jobsJson as JobData[];
export const WORKPLACES = workplacesJson as WorkplaceData[];
export const RESIDENCES = residencesJson as ResidenceData[];
export const DECOR = decorJson as DecorData[];
export const PATHS = pathsJson as PathData[];
export const TREES = treesJson as TreeData[];
export const LAND = landJson as LandRow[];

export const JOB = new Map(JOBS.map((j) => [j.name, j]));
export const WORKPLACE = new Map(WORKPLACES.map((w) => [w.name, w]));
export const RESIDENCE = new Map(RESIDENCES.map((r) => [r.name, r]));
export const DECOR_BY = new Map(DECOR.map((d) => [d.name, d]));
export const PATH = new Map(PATHS.map((p) => [p.name, p]));
export const TREE = new Map(TREES.map((t) => [t.name, t]));

export type Kind = 'workplace' | 'residence' | 'decor' | 'path' | 'tree';

/** Kind of a static id. Workplaces win (SpacePort, Town Hall...). */
export function kindOf(type: string): Kind {
  if (WORKPLACE.has(type)) return 'workplace';
  if (RESIDENCE.has(type)) return 'residence';
  if (DECOR_BY.has(type)) return 'decor';
  if (PATH.has(type)) return 'path';
  return 'tree';
}

/** Footprint cells relative to the anchor cell (03 §1.2). Flip swaps dx and dy. */
export function footprint(type: string, flip = false): [number, number][] {
  const k = kindOf(type);
  const cells = k === 'workplace' ? WORKPLACE.get(type)!.cells
    : k === 'residence' ? RESIDENCE.get(type)!.cells
    : k === 'decor' ? DECOR_BY.get(type)!.cells : [[0, 0]];
  return cells.map(([dx, dy]) => (flip ? [dy, dx] : [dx, dy]) as [number, number]);
}

/** Land the object uses on the land counter (03 §2.1). */
export function landUse(type: string): number {
  switch (kindOf(type)) {
    case 'workplace': return WORKPLACE.get(type)!.size;
    case 'residence': return RESIDENCE.get(type)!.landCost;
    case 'decor': return DECOR_BY.get(type)!.landCost;
    case 'path': return PATH.get(type)!.landCost;
    case 'tree': return TREE.get(type)?.landCost ?? 1;
  }
}

export function displayName(type: string): string {
  return WORKPLACE.get(type)?.displayName ?? RESIDENCE.get(type)?.displayName
    ?? DECOR_BY.get(type)?.displayName ?? PATH.get(type)?.displayName ?? TREE.get(type)?.displayName ?? type;
}

export function jobDisplay(job: string): string {
  return JOB.get(job)?.displayName ?? job.replace(/_/g, ' ');
}
